$ErrorActionPreference = "Continue"; $baseUrl = "http://127.0.0.1:5000"; $tests = @(@{Name="Health check";Url="$baseUrl/health"},@{Name="Traffic per hari";Url="$baseUrl/api/monitoring/traffic?interval=day"},@{Name="Traffic per jam";Url="$baseUrl/api/monitoring/traffic?interval=hour"}); $passed=0; $failed=0; foreach($t in $tests){Write-Host "`n=== $($t.Name) ===" -ForegroundColor Cyan; try{$r=Invoke-RestMethod -Uri $t.Url -Method Get -TimeoutSec 15; Write-Host "HTTP: berhasil" -ForegroundColor Green; if($t.Name -eq "Health check"){$r|ConvertTo-Json -Depth 6}else{$items=@(); if($null -ne $r.data.data){$items=@($r.data.data)}; Write-Host "Jumlah data: $($items.Count)"; if($items.Count -gt 0){Write-Host "Data pertama:"; $items[0]|ConvertTo-Json -Depth 4; Write-Host "Data terakhir:"; $items[-1]|ConvertTo-Json -Depth 4}else{$r|ConvertTo-Json -Depth 5}}; $passed++}catch{Write-Host "GAGAL: $($_.Exception.Message)" -ForegroundColor Red; $failed++}}; Write-Host "`n===== RINGKASAN TES API ====="; Write-Host "Berhasil: $passed"; Write-Host "Gagal: $failed"; if($failed -gt 0){exit 1}else{exit 0}
